import {
  APPROVAL_STATUSES,
  AUDIT_ACTORS,
  MESSAGE_ROLES,
  PROVIDER_KINDS,
  RUN_STATUSES,
  RUN_TRIGGERS,
  TOOL_CALL_STATUSES,
  TOOL_PERMISSIONS,
} from '@ea/shared';
import { sql } from 'drizzle-orm';
import {
  type AnySQLiteColumn,
  index,
  integer,
  primaryKey,
  real,
  sqliteTable,
  text,
  uniqueIndex,
} from 'drizzle-orm/sqlite-core';

// Conventions: ULID text ids generated by the server; UTC ISO-8601 timestamps.

const now = sql`(strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))`;
const id = () => text('id').primaryKey();
const createdAt = () => text('created_at').notNull().default(now);
const updatedAt = () => text('updated_at').notNull().default(now);

export const projects = sqliteTable('projects', {
  id: id(),
  name: text('name').notNull().unique(),
  description: text('description').notNull().default(''),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const providers = sqliteTable('providers', {
  id: id(),
  name: text('name').notNull().unique(),
  kind: text('kind', { enum: PROVIDER_KINDS }).notNull(),
  baseUrl: text('base_url').notNull(),
  /** True when requests leave this machine. Drives the privacy notice (RF-44). */
  isExternal: integer('is_external', { mode: 'boolean' }).notNull(),
  /** Name of the entry in the OS credential vault. Never the secret itself (C-08). */
  secretRef: text('secret_ref'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const models = sqliteTable(
  'models',
  {
    id: id(),
    providerId: text('provider_id')
      .notNull()
      .references(() => providers.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    displayName: text('display_name').notNull(),
    supportsTools: integer('supports_tools', { mode: 'boolean' }).notNull().default(false),
    enabled: integer('enabled', { mode: 'boolean' }).notNull().default(true),
    createdAt: createdAt(),
  },
  (table) => [uniqueIndex('models_provider_name_unique').on(table.providerId, table.name)],
);

export const agents = sqliteTable(
  'agents',
  {
    id: id(),
    projectId: text('project_id').references(() => projects.id, { onDelete: 'set null' }),
    name: text('name').notNull(),
    description: text('description').notNull().default(''),
    objective: text('objective').notNull().default(''),
    systemPrompt: text('system_prompt').notNull().default(''),
    // "restrict" enforces RN-08: a provider/model in use by an agent cannot be removed.
    modelId: text('model_id').references(() => models.id, { onDelete: 'restrict' }),
    temperature: real('temperature').notNull().default(0.7),
    maxOutputTokens: integer('max_output_tokens').notNull().default(4096),
    maxSteps: integer('max_steps').notNull().default(20),
    maxDurationSeconds: integer('max_duration_seconds').notNull().default(300),
    maxTotalTokens: integer('max_total_tokens'),
    enabled: integer('enabled', { mode: 'boolean' }).notNull().default(true),
    /** Soft delete keeps run history readable (RN-07). */
    deletedAt: text('deleted_at'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    index('agents_project_idx').on(table.projectId),
    index('agents_model_idx').on(table.modelId),
  ],
);

export const agentTools = sqliteTable(
  'agent_tools',
  {
    agentId: text('agent_id')
      .notNull()
      .references(() => agents.id, { onDelete: 'cascade' }),
    toolName: text('tool_name').notNull(),
    permission: text('permission', { enum: TOOL_PERMISSIONS }).notNull(),
  },
  (table) => [primaryKey({ columns: [table.agentId, table.toolName] })],
);

export const conversations = sqliteTable(
  'conversations',
  {
    id: id(),
    agentId: text('agent_id')
      .notNull()
      .references(() => agents.id, { onDelete: 'restrict' }),
    title: text('title').notNull().default(''),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [index('conversations_agent_idx').on(table.agentId)],
);

export const runs = sqliteTable(
  'runs',
  {
    id: id(),
    agentId: text('agent_id')
      .notNull()
      .references(() => agents.id, { onDelete: 'restrict' }),
    conversationId: text('conversation_id').references(() => conversations.id, {
      onDelete: 'set null',
    }),
    /** Delegation builds a tree of runs (RF-61). */
    parentRunId: text('parent_run_id').references((): AnySQLiteColumn => runs.id, {
      onDelete: 'set null',
    }),
    trigger: text('trigger', { enum: RUN_TRIGGERS }).notNull(),
    status: text('status', { enum: RUN_STATUSES }).notNull().default('queued'),
    endReason: text('end_reason'),
    errorMessage: text('error_message'),
    inputTokens: integer('input_tokens').notNull().default(0),
    outputTokens: integer('output_tokens').notNull().default(0),
    startedAt: text('started_at'),
    finishedAt: text('finished_at'),
    createdAt: createdAt(),
  },
  (table) => [
    index('runs_agent_idx').on(table.agentId),
    index('runs_conversation_idx').on(table.conversationId),
    index('runs_parent_idx').on(table.parentRunId),
    index('runs_status_idx').on(table.status),
    index('runs_created_idx').on(table.createdAt),
  ],
);

export const messages = sqliteTable(
  'messages',
  {
    id: id(),
    conversationId: text('conversation_id')
      .notNull()
      .references(() => conversations.id, { onDelete: 'cascade' }),
    runId: text('run_id').references(() => runs.id, { onDelete: 'set null' }),
    role: text('role', { enum: MESSAGE_ROLES }).notNull(),
    content: text('content', { mode: 'json' }).notNull(),
    createdAt: createdAt(),
  },
  (table) => [index('messages_conversation_idx').on(table.conversationId, table.createdAt)],
);

export const runSteps = sqliteTable(
  'run_steps',
  {
    id: id(),
    runId: text('run_id')
      .notNull()
      .references(() => runs.id, { onDelete: 'cascade' }),
    /** Monotonic per run; lets an SSE client resume after the last event it saw. */
    seq: integer('seq').notNull(),
    type: text('type').notNull(),
    payload: text('payload', { mode: 'json' }).notNull(),
    createdAt: createdAt(),
  },
  (table) => [uniqueIndex('run_steps_run_seq_unique').on(table.runId, table.seq)],
);

export const toolCalls = sqliteTable(
  'tool_calls',
  {
    id: id(),
    runId: text('run_id')
      .notNull()
      .references(() => runs.id, { onDelete: 'cascade' }),
    toolName: text('tool_name').notNull(),
    arguments: text('arguments', { mode: 'json' }).notNull(),
    permissionDecision: text('permission_decision', { enum: TOOL_PERMISSIONS }).notNull(),
    status: text('status', { enum: TOOL_CALL_STATUSES }).notNull().default('pending'),
    result: text('result', { mode: 'json' }),
    errorMessage: text('error_message'),
    startedAt: text('started_at'),
    finishedAt: text('finished_at'),
    createdAt: createdAt(),
  },
  (table) => [index('tool_calls_run_idx').on(table.runId)],
);

export const approvals = sqliteTable(
  'approvals',
  {
    id: id(),
    runId: text('run_id')
      .notNull()
      .references(() => runs.id, { onDelete: 'cascade' }),
    toolCallId: text('tool_call_id')
      .notNull()
      .references(() => toolCalls.id, { onDelete: 'cascade' }),
    status: text('status', { enum: APPROVAL_STATUSES }).notNull().default('pending'),
    reason: text('reason'),
    decidedAt: text('decided_at'),
    createdAt: createdAt(),
  },
  (table) => [
    index('approvals_status_idx').on(table.status),
    uniqueIndex('approvals_tool_call_unique').on(table.toolCallId),
  ],
);

/**
 * Sensitive operations. Agent and run ids are plain text, not foreign keys,
 * so entries survive the removal of what they refer to.
 */
export const auditLog = sqliteTable(
  'audit_log',
  {
    id: id(),
    occurredAt: text('occurred_at').notNull().default(now),
    actor: text('actor', { enum: AUDIT_ACTORS }).notNull(),
    agentId: text('agent_id'),
    runId: text('run_id'),
    action: text('action').notNull(),
    target: text('target'),
    details: text('details', { mode: 'json' }),
  },
  (table) => [index('audit_log_occurred_idx').on(table.occurredAt)],
);

export const settings = sqliteTable('settings', {
  key: text('key').primaryKey(),
  value: text('value', { mode: 'json' }).notNull(),
  updatedAt: updatedAt(),
});
